export const BONUS_WORDS: ReadonlySet<string> = new Set(BONUS_WORD_BLOB.split(' '))

/** True if `word` (>=3 letters) is a known common English word. */
export function isBonusWord(word: string): boolean {
  return word.length >= 3 && BONUS_WORDS.has(word.toUpperCase())
}
